-- ECONOLAB: respaldo analitico anonimizado
-- Generado por 04_ETL/exportar_respaldo_analitico_anonimizado.js
-- No contiene datos personales de pacientes, medicos o usuarios.

BEGIN;

DROP SCHEMA IF EXISTS operativo CASCADE;
CREATE SCHEMA operativo;

CREATE TABLE operativo.studies (
  id integer PRIMARY KEY,
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  type text NOT NULL,
  status text NOT NULL,
  "isActive" boolean NOT NULL,
  "normalPrice" numeric(12, 2),
  "durationMinutes" integer,
  method text,
  "sampleType" text,
  "requiresSpecialProcessing" boolean,
  indicator text,
  "isSynthetic" boolean NOT NULL
);

CREATE TABLE operativo.study_details (
  id integer PRIMARY KEY,
  study_id integer NOT NULL REFERENCES operativo.studies(id),
  "dataType" text NOT NULL,
  "isActive" boolean NOT NULL
);

CREATE TABLE operativo.service_orders (
  id integer PRIMARY KEY,
  folio text NOT NULL UNIQUE,
  "branchName" text,
  "sampleAt" timestamp without time zone,
  "deliveryAt" timestamp without time zone,
  "completedAt" timestamp without time zone,
  status text NOT NULL,
  "subtotalAmount" numeric(12, 2) NOT NULL,
  "courtesyPercent" numeric(6, 2) NOT NULL,
  "discountAmount" numeric(12, 2) NOT NULL,
  "totalAmount" numeric(12, 2) NOT NULL,
  "isActive" boolean NOT NULL,
  "createdAt" timestamp without time zone NOT NULL,
  "isSynthetic" boolean NOT NULL
);

CREATE TABLE operativo.service_order_items (
  id integer PRIMARY KEY,
  service_order_id integer NOT NULL REFERENCES operativo.service_orders(id),
  study_id integer NOT NULL REFERENCES operativo.studies(id),
  "priceType" text NOT NULL,
  "unitPrice" numeric(12, 2) NOT NULL,
  quantity integer NOT NULL,
  "discountPercent" numeric(6, 2) NOT NULL,
  "subtotalAmount" numeric(12, 2) NOT NULL,
  source_package_id integer
);


ALTER TABLE operativo.service_orders ADD COLUMN "updatedAt" timestamp without time zone NOT NULL;

